function createAccount(name,x,state){
  const f=fr(name,414,932,C.white,0,x,100);
  statusBar(f,false);
  icon('6:275',f,30,62,C.ink,1);
  tx(f,'Title','Create an account',F.db,28,34,C.ink,30,104,354);
  tx(f,'Sub','Invest and double your income now',F.fr,15,22,C.ink2,30,144,354);
  const fields=[
    {label:'Full name',ph:'Enter your full name',val:'Jonas Macroni'},
    {label:'Email address',ph:'Enter your email',val:'jonas.macroni@invest.ai'},
    {label:'Password',ph:'Enter your password',val:'••••••••••'}
  ];
  let y=204;
  fields.forEach((fd,i)=>{
    tx(f,'Label '+fd.label,fd.label,F.fm,13,18,C.ink2,30,y,354);
    const isErr = state==='error' && fd.label==='Email address';
    const filledNow = state==='filled';
    const comp = isErr?'2006:43':(filledNow?'2006:41':'2006:37');
    const inst=figma.getNodeById(comp).createInstance(); inst.name='Field '+fd.label; f.appendChild(inst);
    inst.x=30; inst.y=y+24; inst.resize(354,60);
    const lab=inst.children[0];
    if(isErr){ lab.characters='jonas.macroni@invest'; }
    else if(filledNow){ lab.characters=fd.val; lab.fills=[solid(C.ink)]; }
    else { lab.characters=fd.ph; lab.fills=[solid(C.ink3)]; }
    if(fd.label==='Password' && filledNow){
      icon('6:279',f,388,0,C.ink3,1); // placeholder position fixed below
      const eye=f.children[f.children.length-1]; eye.name='Icon Show Password'; eye.x=336-16; eye.y=y+24+18;
      try{ eye.children.forEach(c=>{}); }catch(e){}
    }
    y+=104;
  });
  if(state==='error'){
    icon('6:274',f,30,y-104+84,C.danger,0.8); f.children[f.children.length-1].name='Error Icon';
    tx(f,'Error msg','Enter a valid email address',F.fm,13,18,C.danger,30,y-6,354);
    y+=26;
  }
  const btn = state==='filled'?'2006:25':'2006:29';
  const bi=figma.getNodeById(btn).createInstance(); bi.name='Button · Create account'; f.appendChild(bi);
  bi.x=30; bi.y=740; bi.children[0].characters='Create account';
  tx(f,'Login row','Already have an account?  Login',F.fm,14,20,C.ink2,0,816,414,'CENTER');
  homeIndicator(f,false);
  return f;
}
